def first_cohomology_dimension(d0: Sequence[Sequence[float]], d1: Sequence[Sequence[float]], tolerance: float = 1e-10) -> int:
    """Return dim ker(d1) - dim im(d0), after checking d1 @ d0 = 0."""
    a = np.asarray(d0, dtype=float)
    b = np.asarray(d1, dtype=float)
    if a.ndim != 2 or b.ndim != 2 or b.shape[1] != a.shape[0]:
